async function j(u: string) { try { const r = await tools.web_fetch({ url: u }); return JSON.parse(r.body.content); } catch (e) { return { error: String(e).slice(0,200) }; } }
async function t(u: string, n=6000) { try { const r = await tools.web_fetch({ url: u }); return (r.body.content||"").slice(0,n); } catch (e) { return "ERR " + String(e).slice(0,200); } }

const [readme, search, topics] = await Promise.all([
  t("https://raw.githubusercontent.com/Ebony-Vinyl/dsh-our-free-model/main/README.md", 9000),
  j("https://api.github.com/search/repositories?q=topic:dsh-plugin&sort=stars&order=desc&per_page=30"),
  t("https://github.com/topics/dsh-plugin", 4000),
]);
console.log("README:\n", readme);
if (search?.items) {
  console.log("\n\n=== dsh-plugin repos by stars ===");
  for (const it of search.items) console.log(`${it.stargazers_count}\t${it.full_name}\t${(it.description||"").slice(0,90)}`);
} else console.log("SEARCH ERR", JSON.stringify(search).slice(0,300));
console.log("\nTOPICS PAGE:\n", topics.slice(0, 1500));
